    if(visible(p).some(r=>r.id!==d.id&&r.domain===d.domain&&r.name===values.name)){document.getElementById('biz-error').textContent='当前范围已有同名记录。';return;}
    if(p.id==='response/policies'){const target=api.visibleAssets().find(a=>a.id===values.assetId&&a.domain===d.domain);if(!target){document.getElementById('biz-error').textContent='请选择当前域内的明确资产。';return;}if((target.type==='计算机'&&values.effect!=='限制设备访问')||(target.type==='用户'&&values.effect!=='限制账户访问')){document.getElementById('biz-error').textContent='响应动作需与目标对象类型一致。';return;}values.target=target.name;values.targetGuid=target.guid;}
