    let text,type,name;
    if(p.kind==='reports'&&records.length===1){text='<!doctype html><meta charset="utf-8"><title>ADTR 演示报告</title>'+reportBody(records[0]);type='text/html;charset=utf-8';name='ADTR_DEMO_REPORT.html';}
    else {const cs=p.columns;text='\uFEFF'+cs.map(c=>c.label).join(',')+'\r\n'+records.map(r=>cs.map(c=>'"'+pretty(r[c.key]).replace(/"/g,'""')+'"').join(',')).join('\r\n');type='text/csv;charset=utf-8';name='ADTR_DEMO_'+p.id.replace('/','_')+'.csv';}
    const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);audit('下载'+p.title,p.title,'成功',records[0]?.domain||'platform');toast('文件已生成。');
